CREATE DATABASE IF NOT EXISTS overso CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE overso;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS recently_viewed, reviews, payments, order_items, orders, coupon_usage, coupons, addresses, wishlist, cart, product_sizes, products, categories, admins, users;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(120) NOT NULL UNIQUE, mobile VARCHAR(15) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, address TEXT, profile_image VARCHAR(255) DEFAULT NULL, status ENUM('blocked','active') NOT NULL DEFAULT 'blocked', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status));
CREATE TABLE admins (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255), image VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT NOT NULL, name VARCHAR(150) NOT NULL, brand VARCHAR(80) NOT NULL DEFAULT 'OVERSO', description TEXT NOT NULL, specifications TEXT, material VARCHAR(80) DEFAULT '240 GSM Cotton', fit_type VARCHAR(80) DEFAULT 'Relaxed Oversized Fit', color VARCHAR(50) NOT NULL, original_price DECIMAL(10,2) NOT NULL, discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0, image VARCHAR(255) DEFAULT 'assets/images/products/tee.svg', additional_images TEXT, stock_quantity INT NOT NULL DEFAULT 0, sales_count INT DEFAULT 0, rating DECIMAL(3,2) DEFAULT 0, review_count INT DEFAULT 0, status ENUM('active','inactive','out_of_stock','discontinued') DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX(category_id), INDEX(status), INDEX(color));
CREATE TABLE product_sizes (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, size ENUM('S','M','L','XL','XXL','XXXL') NOT NULL, stock_quantity INT NOT NULL DEFAULT 0, UNIQUE KEY product_size(product_id,size), FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE cart (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,size VARCHAR(10) NOT NULL,quantity INT NOT NULL DEFAULT 1, UNIQUE KEY user_product_size(user_id,product_id,size),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE wishlist (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY user_product(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE addresses (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,full_name VARCHAR(100) NOT NULL,mobile VARCHAR(15) NOT NULL,address TEXT NOT NULL,city VARCHAR(60) NOT NULL,state VARCHAR(60) NOT NULL,pincode VARCHAR(10) NOT NULL,is_default TINYINT(1) DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE coupons (id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,discount_type ENUM('percent','flat') NOT NULL,discount_value DECIMAL(10,2) NOT NULL,minimum_order DECIMAL(10,2) DEFAULT 0,maximum_discount DECIMAL(10,2) DEFAULT NULL,expiry_date DATE NOT NULL,usage_limit INT DEFAULT 100,used_count INT DEFAULT 0,status ENUM('active','inactive') DEFAULT 'active');
CREATE TABLE coupon_usage (id INT AUTO_INCREMENT PRIMARY KEY,coupon_id INT NOT NULL,user_id INT NOT NULL,order_id INT NULL,used_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(coupon_id) REFERENCES coupons(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE orders (id INT AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(30) UNIQUE NOT NULL,user_id INT NOT NULL,coupon_id INT NULL,shipping_address TEXT NOT NULL,billing_address TEXT NOT NULL,subtotal DECIMAL(10,2) NOT NULL,coupon_discount DECIMAL(10,2) DEFAULT 0,tax DECIMAL(10,2) DEFAULT 0,delivery_charge DECIMAL(10,2) DEFAULT 0,total_amount DECIMAL(10,2) NOT NULL,payment_method ENUM('cod','upi','card','netbanking') NOT NULL,payment_status ENUM('pending','paid','failed') DEFAULT 'pending',order_status ENUM('pending','confirmed','packed','shipped','out_for_delivery','delivered','cancelled') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(coupon_id) REFERENCES coupons(id),INDEX(order_status));
CREATE TABLE order_items (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NOT NULL,product_name VARCHAR(150) NOT NULL,size VARCHAR(10) NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL UNIQUE,method VARCHAR(20) NOT NULL,amount DECIMAL(10,2) NOT NULL,status ENUM('pending','paid','failed') DEFAULT 'pending',transaction_ref VARCHAR(60),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE reviews (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,rating TINYINT NOT NULL,review_text TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY user_product_review(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE recently_viewed (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,product_id INT NOT NULL,viewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY user_product_recent(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);

