INSERT INTO product_sizes(product_id,size,stock_quantity) SELECT p.id,s.size,CASE WHEN p.stock_quantity=0 THEN 0 WHEN s.size='XXXL' THEN FLOOR(p.stock_quantity/8) ELSE FLOOR(p.stock_quantity/5) END FROM products p CROSS JOIN (SELECT 'S' size UNION SELECT 'M' UNION SELECT 'L' UNION SELECT 'XL' UNION SELECT 'XXL' UNION SELECT 'XXXL') s;
